// Validates the first line of a commit message against Conventional Commits (D-013).
import { readFileSync } from "node:fs";

const TYPES = [
  "feat",
  "fix",
  "docs",
  "style",
  "refactor",
  "perf",
  "test",
  "build",
  "ci",
  "chore",
  "revert",
];
const HEADER = new RegExp(`^(${TYPES.join("|")})(\\([a-z0-9-]+\\))?!?: \\S.{0,99}$`);
// Messages generated by git itself are allowed as-is.
const GIT_GENERATED = /^(Merge |Revert "|fixup! |squash! |amend! )/;

const file = process.argv[2];
if (!file) {
  console.error("Usage: check-commit-msg.mjs <commit-msg-file>");
  process.exit(2);
}

const header = readFileSync(file, "utf8").split("\n", 1)[0]?.trim() ?? "";

if (!GIT_GENERATED.test(header) && !HEADER.test(header)) {
  console.error(`✖ Invalid commit message: "${header}"`);
  console.error("  Expected: <type>(<scope>)?: <description>  (max 100 chars after the colon)");
  console.error(`  Types: ${TYPES.join(", ")}`);
  console.error("  Example: feat(core): compute booster refill from elapsed time");
  process.exit(1);
}
